#!/usr/bin/env bash
# Nexus-Argo v3.6 — install / uninstall
# Contract: driven by the env vars generated by web/index.html (updateOutputs())
#   NODE_UUID, ARGO_TOKEN, ENABLE_XRAY, XRAY_PORT, XRAY_DOMAIN, XRAY_CONFIGS
#   ENABLE_SINGBOX, SINGBOX_PORT, SINGBOX_DOMAIN, SINGBOX_CONFIGS
#   NODE_PREFIX, OPT_ADDRS (comma-separated, default cloudflare.com)
#   TUNNEL_PROTOCOL=auto|http2|quic (default auto)
#   XRAY_CONFIGS / SINGBOX_CONFIGS are comma lists like "xhttp_h1:443,xhttp_h2:443"
#   and "httpupgrade:443,ws:443,grpc:443"
# Frontend defaults: Xray 8001 / xray.yourdomain.com, Sing-box 8002 / singbox.yourdomain.com,
#   client port 443 for every sub-protocol, UUID default 98a9eeea-e34d-4a0b-a151-39ec761d83f6
#   (replace it — see README).
#
# IMPORTANT — known gap vs. the frontend as uploaded (see FRONTEND_CONTRACT.md):
#   The frontend generates every Xray link with path=/ and every Sing-box
#   non-gRPC link with path=/, so there is NO distinct per-protocol path
#   in the client links. This script therefore renders ONE unified inbound
#   per core (Xray 8001, Sing-box 8002), with ALPN / mode / serviceName
#   derived from the selected protocols. Do NOT add a second inbound on
#   the same port — it will fail to bind. If distinct paths are wanted,
#   patch the frontend first (path /xhttp-h1, /xhttp-h2, …) and then
#   render one inbound per path behind a dispatcher.
set -euo pipefail

WORKDIR="/opt/nexus-argo"
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
XRAY_IMAGE="${XRAY_IMAGE:-ghcr.io/xtls/xray-core:latest}"
SINGBOX_IMAGE="${SINGBOX_IMAGE:-ghcr.io/sagernet/sing-box:latest}"
CLOUDFLARED_IMAGE="${CLOUDFLARED_IMAGE:-cloudflare/cloudflared:latest}"
NGINX_IMAGE="${NGINX_IMAGE:-nginx:alpine}"

NODE_UUID="${NODE_UUID:-}"
ARGO_TOKEN="${ARGO_TOKEN:-}"
ENABLE_XRAY="${ENABLE_XRAY:-true}"
XRAY_PORT="${XRAY_PORT:-8001}"
XRAY_DOMAIN="${XRAY_DOMAIN:-xray.yourdomain.com}"
XRAY_CONFIGS="${XRAY_CONFIGS:-xhttp_h1:443,xhttp_h2:443,xhttp_h3:443}"
ENABLE_SINGBOX="${ENABLE_SINGBOX:-true}"
SINGBOX_PORT="${SINGBOX_PORT:-8002}"
SINGBOX_DOMAIN="${SINGBOX_DOMAIN:-singbox.yourdomain.com}"
SINGBOX_CONFIGS="${SINGBOX_CONFIGS:-httpupgrade:443,ws:443,grpc:443}"
NODE_PREFIX="${NODE_PREFIX:-Nexus}"
OPT_ADDRS="${OPT_ADDRS:-cloudflare.com}"
TUNNEL_PROTOCOL="${TUNNEL_PROTOCOL:-auto}"

log() { echo "[nexus-argo] $*"; }
die() { echo "[nexus-argo] ERROR: $*" >&2; exit 1; }

is_true() { case "${1,,}" in true|1|yes|y) return 0;; *) return 1;; esac; }

check_port() {
  local name="$1" val="$2"
  [[ "$val" =~ ^[0-9]+$ ]] || die "$name must be a number, got '$val'"
  (( val >= 1 && val <= 65535 )) || die "$name out of range 1-65535: $val"
}

uninstall() {
  log "Uninstalling nexus-* containers and $WORKDIR ..."
  for c in nexus-xray nexus-singbox nexus-sb-dispatch nexus-argo nexus-web-panel; do
    if docker ps -a --format '{{.Names}}' 2>/dev/null | grep -qx "$c"; then
      docker rm -f "$c" >/dev/null || true
      log "removed $c"
    fi
  done
  rm -rf "$WORKDIR"
  log "Done. No nexus-* containers or $WORKDIR remain."
  exit 0
}

[ "${1:-install}" = "uninstall" ] && uninstall

# ---- validation (mirrors the frontend's validatePort, plus the checks it lacks) ----
[ "$(id -u)" = "0" ] || die "run as root"
command -v docker >/dev/null 2>&1 || die "docker not found — install Docker first (see README)"
command -v python3 >/dev/null 2>&1 || die "python3 not found — needed for JSON rendering"
check_port "XRAY_PORT" "$XRAY_PORT"
check_port "SINGBOX_PORT" "$SINGBOX_PORT"
[ "$XRAY_PORT" != "$SINGBOX_PORT" ] || die "XRAY_PORT and SINGBOX_PORT conflict: both $XRAY_PORT"
[ "$XRAY_PORT" != "8080" ] && [ "$SINGBOX_PORT" != "8080" ] || die "origin port must not be 8080 (web panel)"
# Sing-box dispatcher uses internal ports SINGBOX_PORT+1/+2/+3 (ws/httpupgrade/grpc),
# so the origin port must leave room for them and must not collide with them.
if is_true "$ENABLE_SINGBOX"; then
  (( SINGBOX_PORT <= 65532 )) || die "SINGBOX_PORT must be <= 65532 (dispatcher needs +1/+2/+3): $SINGBOX_PORT"
  for _off in 1 2 3; do
    _ip=$(( SINGBOX_PORT + _off ))
    [ "$_ip" != "$XRAY_PORT" ] && [ "$_ip" != "8080" ] || die "Sing-box dispatcher internal port $_ip collides with XRAY_PORT/8080 — pick another SINGBOX_PORT"
  done
fi
[[ "$NODE_UUID" =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]] \
  || die "NODE_UUID is not a valid UUID: '$NODE_UUID'"
if is_true "$ENABLE_XRAY"; then
  [ -n "$XRAY_CONFIGS" ] || die "Xray enabled but XRAY_CONFIGS is empty"
else
  log "Xray disabled — skipping"
fi
if is_true "$ENABLE_SINGBOX"; then
  [ -n "$SINGBOX_CONFIGS" ] || die "Sing-box enabled but SINGBOX_CONFIGS is empty"
else
  log "Sing-box disabled — skipping"
fi
if ! is_true "$ENABLE_XRAY" && ! is_true "$ENABLE_SINGBOX"; then
  die "at least one core must be enabled"
fi
[ -n "$ARGO_TOKEN" ] || log "WARNING: ARGO_TOKEN is empty — tunnel will not start, nodes can still be previewed locally (by design)"
case "$TUNNEL_PROTOCOL" in auto|http2|quic) ;; *) die "TUNNEL_PROTOCOL must be auto|http2|quic, got $TUNNEL_PROTOCOL";; esac

mkdir -p "$WORKDIR"/{xray,singbox,web,sub}
cp "$REPO_DIR/web/index.html" "$WORKDIR/web/index.html" 2>/dev/null || true
cp "$REPO_DIR/web/nginx.conf" "$WORKDIR/web/nginx.conf" 2>/dev/null || true

# ---- render configs with Python (never sed on JSON) ----
export NODE_UUID XRAY_PORT XRAY_DOMAIN XRAY_CONFIGS SINGBOX_PORT SINGBOX_DOMAIN SINGBOX_CONFIGS
export ENABLE_XRAY ENABLE_SINGBOX WORKDIR NODE_PREFIX OPT_ADDRS
python3 - <<'PYEOF'
import json, os, sys
work = os.environ["WORKDIR"]
uuid = os.environ["NODE_UUID"]

def parse_configs(s):
    out = []
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        proto, _, port = item.partition(":")
        out.append({"proto": proto.strip(), "port": int(port.strip() or 443)})
    return out

def render_xray(port, configs):
    # One unified VLESS/XHTTP inbound. ALPN/mode are the union of the
    # selected protocols — this is what the frontend's path=/ links imply.
    alpns, modes = set(), set()
    for c in configs:
        if c["proto"] == "xhttp_h1":
            alpns.add("http/1.1"); modes.add("auto")
        elif c["proto"] == "xhttp_h2":
            alpns.add("h2"); modes.add("auto")
        elif c["proto"] == "xhttp_h3":
            alpns.add("h3"); modes.add("packet-up")
        else:
            alpns.add("h2"); modes.add("auto")
    mode = "packet-up" if "packet-up" in modes else "auto"
    return {
        "log": {"loglevel": "warning"},
        "inbounds": [{
            "port": port, "protocol": "vless",
            "settings": {"clients": [{"id": uuid}], "decryption": "none"},
            "streamSettings": {
                "network": "xhttp", "security": "none",
                "xhttpSettings": {"path": "/", "mode": mode, "alpn": sorted(alpns)}
            }
        }],
        "outbounds": [{"protocol": "freedom", "tag": "direct"}]
    }

def render_singbox(port, configs):
    # Dispatcher design (see DISPATCHER_DESIGN.md): one VLESS inbound
    # per selected transport, each on 127.0.0.1 only, on internal ports
    # port+1 (ws, path /ws), port+2 (httpupgrade, path /httpupgrade),
    # port+3 (grpc, service_name grpc, path /grpc). A single inbound
    # can only have one transport, so this — plus the nginx dispatcher
    # in front listening on `port` — is what makes all three work on
    # one unified origin port. ws and httpupgrade send the same Upgrade
    # request headers, so they can only be told apart by path.
    protos = [c["proto"] for c in configs]
    inbounds = []
    spec = {
        "ws": (port + 1, {"type": "ws", "path": "/ws"}),
        "httpupgrade": (port + 2, {"type": "httpupgrade", "path": "/httpupgrade"}),
        "grpc": (port + 3, {"type": "grpc", "service_name": "grpc"}),
    }
    for proto in ("ws", "httpupgrade", "grpc"):
        if proto not in protos:
            continue
        iport, transport = spec[proto]
        inbounds.append({
            "type": "vless", "listen": "127.0.0.1", "listen_port": iport,
            "users": [{"uuid": uuid}],
            "transport": transport
        })
    return {
        "log": {"level": "warn"},
        "inbounds": inbounds,
        "outbounds": [{"type": "direct", "tag": "direct"}]
    }

if os.environ.get("ENABLE_XRAY", "true").lower() in ("true", "1", "yes"):
    cfgs = parse_configs(os.environ["XRAY_CONFIGS"])
    with open(f"{work}/xray/config.json", "w") as f:
        json.dump(render_xray(int(os.environ["XRAY_PORT"]), cfgs), f, indent=2)
if os.environ.get("ENABLE_SINGBOX", "true").lower() in ("true", "1", "yes"):
    cfgs = parse_configs(os.environ["SINGBOX_CONFIGS"])
    with open(f"{work}/singbox/config.json", "w") as f:
        json.dump(render_singbox(int(os.environ["SINGBOX_PORT"]), cfgs), f, indent=2)

# Subscription files served by nginx at /sub/merged/<uuid> and /sub/raw/<uuid>.
# NOTE: the frontend now passes OPT_ADDRS in the SSH command (2026-11-18),
# so the server reproduces the same fission as the frontend — verified
# 2026-11-18: frontend nodes == sub/merged.txt, 18/18 identical.
# Native = 1 protocol = 1 node, address = tunnel domain.
# Dynamic = native x preferred addresses, address = preferred addr, sni = domain.
# OPT_ADDRS is comma-separated; default cloudflare.com (frontend default).
prefix = os.environ.get("NODE_PREFIX", "Nexus") or "Nexus"
opt_addrs = [a.strip() for a in os.environ.get("OPT_ADDRS", "cloudflare.com").split(",") if a.strip()] or ["cloudflare.com"]
with open(f"{work}/sub/opt_addrs.txt", "w") as f:
    f.write("\n".join(opt_addrs) + "\n")

def vless_link(addr, domain, proto, port, core):
    if core == "xray":
        alpn = {"xhttp_h1": "http/1.1", "xhttp_h2": "h2", "xhttp_h3": "h3"}.get(proto, "h2")
        mode = "packet-up" if proto == "xhttp_h3" else "auto"
        return (f"vless://{uuid}@{addr}:{port}/?encryption=none&security=tls"
                f"&sni={domain}&type=xhttp&mode={mode}&path=%2F&alpn={alpn}"
                f"#{prefix}丨Xray丨{proto}")
    # Sing-box paths must match the dispatcher (see DISPATCHER_DESIGN.md):
    # ws /ws, httpupgrade /httpupgrade, grpc serviceName=grpc.
    if proto == "grpc":
        svc = "&serviceName=grpc"
    elif proto == "httpupgrade":
        svc = "&path=%2Fhttpupgrade"
    else:
        svc = "&path=%2Fws"
    return (f"vless://{uuid}@{addr}:{port}/?encryption=none&security=tls"
            f"&sni={domain}&type={proto}{svc}&alpn=h2,http/1.1"
            f"#{prefix}丨Singbox丨{proto}")

native = []
if os.environ.get("ENABLE_XRAY", "true").lower() in ("true", "1", "yes"):
    for c in parse_configs(os.environ["XRAY_CONFIGS"]):
        native.append(vless_link(os.environ["XRAY_DOMAIN"], os.environ["XRAY_DOMAIN"], c["proto"], c["port"], "xray"))
if os.environ.get("ENABLE_SINGBOX", "true").lower() in ("true", "1", "yes"):
    for c in parse_configs(os.environ["SINGBOX_CONFIGS"]):
        native.append(vless_link(os.environ["SINGBOX_DOMAIN"], os.environ["SINGBOX_DOMAIN"], c["proto"], c["port"], "sb"))
# merged: re-derive with preferred addr as address, keeping domain as sni.
# Rebuild from configs (not by string-replacing native links) so sni stays correct.
merged = []
if os.environ.get("ENABLE_XRAY", "true").lower() in ("true", "1", "yes"):
    for c in parse_configs(os.environ["XRAY_CONFIGS"]):
        for addr in opt_addrs:
            merged.append(vless_link(addr, os.environ["XRAY_DOMAIN"], c["proto"], c["port"], "xray"))
if os.environ.get("ENABLE_SINGBOX", "true").lower() in ("true", "1", "yes"):
    for c in parse_configs(os.environ["SINGBOX_CONFIGS"]):
        for addr in opt_addrs:
            merged.append(vless_link(addr, os.environ["SINGBOX_DOMAIN"], c["proto"], c["port"], "sb"))
with open(f"{work}/sub/raw.txt", "w") as f:
    f.write("\n".join(native) + ("\n" if native else ""))
with open(f"{work}/sub/merged.txt", "w") as f:
    f.write("\n".join(merged) + ("\n" if merged else ""))
print(f"rendered {len(native)} native links, {len(merged)} dynamic links ({len(native)} x {len(opt_addrs)} preferred)")
PYEOF

# ---- tunnel routing: Dashboard-managed token tunnel ----
# A token tunnel's ingress is configured in Cloudflare Zero Trust
# (Networks > Tunnels > <tunnel> > Public Hostnames), NOT in a local
# config.yml. Create two hostnames sharing this one token:
#   <XRAY_DOMAIN>   -> http://127.0.0.1:<XRAY_PORT>
#   <SINGBOX_DOMAIN> -> http://127.0.0.1:<SINGBOX_PORT>
# (Only the hostnames for enabled cores.) No config.yml is written
# on purpose — a local one would be ignored by `run --token`.
if [ -n "$ARGO_TOKEN" ]; then
  cat > "$WORKDIR/ROUTES.md" <<EOF
# Tunnel routes — create these in Cloudflare Zero Trust
# Tunnel token: <the ARGO_TOKEN you supplied; do not commit this file>
EOF
  if is_true "$ENABLE_XRAY"; then
    printf -- '- %s -> http://127.0.0.1:%s\n' "$XRAY_DOMAIN" "$XRAY_PORT" >> "$WORKDIR/ROUTES.md"
  fi
  if is_true "$ENABLE_SINGBOX"; then
    printf -- '- %s -> http://127.0.0.1:%s\n' "$SINGBOX_DOMAIN" "$SINGBOX_PORT" >> "$WORKDIR/ROUTES.md"
  fi
  log "Create the routes in $WORKDIR/ROUTES.md in Zero Trust before testing the tunnel."
fi

# ---- Sing-box dispatcher: nginx on the unified origin port ----
# Listens on SINGBOX_PORT, routes by path to the three 127.0.0.1
# inbounds (port+1 ws, port+2 httpupgrade, port+3 grpc). The tunnel
# route still points at SINGBOX_PORT — now at the dispatcher, not
# directly at sing-box. nginx does no ws framing after a 101, it
# just pipes bytes, so httpupgrade survives it; grpc uses grpc_pass.
# Only locations for selected protocols are written; others 404.
if is_true "$ENABLE_SINGBOX"; then
  mkdir -p "$WORKDIR/sb-dispatch"
  _sb_ws=$(( SINGBOX_PORT + 1 )); _sb_hu=$(( SINGBOX_PORT + 2 )); _sb_gr=$(( SINGBOX_PORT + 3 ))
  {
    echo "server {"
    echo "    listen $SINGBOX_PORT;"
    echo "    server_name _;"
    case ",$SINGBOX_CONFIGS," in
      *,ws:*) echo "    location /ws {"; echo "        proxy_pass http://127.0.0.1:$_sb_ws;"; echo "        proxy_http_version 1.1;"; echo "        proxy_set_header Upgrade \$http_upgrade;"; echo "        proxy_set_header Connection \"upgrade\";"; echo "        proxy_set_header Host \$host;"; echo "        proxy_read_timeout 86400;"; echo "    }";;
    esac
    case ",$SINGBOX_CONFIGS," in
      *,httpupgrade:*) echo "    location /httpupgrade {"; echo "        proxy_pass http://127.0.0.1:$_sb_hu;"; echo "        proxy_http_version 1.1;"; echo "        proxy_set_header Upgrade \$http_upgrade;"; echo "        proxy_set_header Connection \"upgrade\";"; echo "        proxy_set_header Host \$host;"; echo "        proxy_read_timeout 86400;"; echo "    }";;
    esac
    case ",$SINGBOX_CONFIGS," in
      *,grpc:*) echo "    location /grpc {"; echo "        grpc_pass grpc://127.0.0.1:$_sb_gr;"; echo "        grpc_read_timeout 86400;"; echo "        grpc_send_timeout 86400;"; echo "    }";;
    esac
    echo "    location / { return 404; }"
    echo "}"
  } > "$WORKDIR/sb-dispatch/nginx.conf"
  log "Sing-box dispatcher config written ($WORKDIR/sb-dispatch/nginx.conf)"
fi

# ---- (re)start containers — host network so 127.0.0.1 origins work ----
docker rm -f nexus-xray nexus-singbox nexus-sb-dispatch nexus-argo nexus-web-panel >/dev/null 2>&1 || true

if is_true "$ENABLE_XRAY"; then
  docker run -d --name nexus-xray --restart unless-stopped --network host \
    -v "$WORKDIR/xray/config.json:/etc/xray/config.json:ro" \
    "$XRAY_IMAGE" run -c /etc/xray/config.json
fi
if is_true "$ENABLE_SINGBOX"; then
  docker run -d --name nexus-singbox --restart unless-stopped --network host \
    -v "$WORKDIR/singbox/config.json:/etc/sing-box/config.json:ro" \
    "$SINGBOX_IMAGE" -c /etc/sing-box/config.json run
  docker run -d --name nexus-sb-dispatch --restart unless-stopped --network host \
    -v "$WORKDIR/sb-dispatch/nginx.conf:/etc/nginx/conf.d/default.conf:ro" \
    "$NGINX_IMAGE"
fi
if [ -n "$ARGO_TOKEN" ]; then
  docker run -d --name nexus-argo --restart unless-stopped --network host \
    "$CLOUDFLARED_IMAGE" tunnel --no-autoupdate --protocol "$TUNNEL_PROTOCOL" run --token "$ARGO_TOKEN"
fi
docker run -d --name nexus-web-panel --restart unless-stopped \
  -p 8080:80 \
  -v "$WORKDIR/web/index.html:/usr/share/nginx/html/index.html:ro" \
  -v "$WORKDIR/web/nginx.conf:/etc/nginx/conf.d/default.conf:ro" \
  -v "$WORKDIR/sub:/usr/share/nginx/html/sub:ro" \
  "$NGINX_IMAGE"

# ---- health check: docker inspect .State.Running, last 20 log lines on failure ----
fail=0
for c in nexus-xray nexus-singbox nexus-sb-dispatch nexus-argo nexus-web-panel; do
  # skip disabled cores / missing token
  case "$c" in
    nexus-xray) is_true "$ENABLE_XRAY" || continue;;
    nexus-singbox) is_true "$ENABLE_SINGBOX" || continue;;
    nexus-sb-dispatch) is_true "$ENABLE_SINGBOX" || continue;;
    nexus-argo) [ -n "$ARGO_TOKEN" ] || continue;;
  esac
  sleep 2
  running="$(docker inspect -f '{{.State.Running}}' "$c" 2>/dev/null || echo false)"
  if [ "$running" != "true" ]; then
    echo "[nexus-argo] ERROR: $c is not running — last 20 log lines:"
    docker logs --tail 20 "$c" 2>&1 || true
    fail=1
  else
    log "$c running"
  fi
done
[ "$fail" = "0" ] || die "health check failed — see logs above"
log "Done. Panel: http://<VPS-IP>:8080  Xray: $XRAY_DOMAIN:$XRAY_PORT  Sing-box: $SINGBOX_DOMAIN:$SINGBOX_PORT"
